import test from "node:test";
import assert from "node:assert/strict";
import { TTLCache } from "../src/cache.ts";
import { DocumentService } from "../src/service.ts";

for (const now of [110, 111]) {
  test(`cache removes an expired entry at time ${now}`, () => {
    const cache = new TTLCache();
    const value = { title: "Welcome" };
    cache.put("a", value, { now: 100, ttl: 10 });
    assert.equal(cache.get("a", { now: 109 }), value);
    assert.equal(cache.entries.get("a").expires, 110);
    assert.equal(cache.get("a", { now }), undefined);
    assert.equal(cache.entries.has("a"), false);
    assert.equal(cache.get("a", { now: 112 }), undefined);
  });
}

test("overwriting a key starts a new TTL", () => {
  const cache = new TTLCache();
  cache.put("a", "original", { now: 100, ttl: 10 });
  cache.put("a", "replacement", { now: 105, ttl: 20 });
  assert.equal(cache.get("a", { now: 110 }), "replacement");
  assert.equal(cache.get("a", { now: 124 }), "replacement");
  assert.equal(cache.entries.get("a").expires, 125);
  assert.equal(cache.get("a", { now: 125 }), undefined);
  assert.equal(cache.entries.has("a"), false);
});

test("DocumentService respects the cache deadline", () => {
  const service = new DocumentService();
  const document = service.repository.create("a", { title: "Welcome" });
  service.cache.put("a", document, { now: 100, ttl: 10 });
  assert.equal(service.cachedDocument("a", 109), document);
  assert.equal(service.cache.entries.get("a").expires, 110);
  assert.equal(service.cachedDocument("a", 110), undefined);
  assert.equal(service.cache.entries.has("a"), false);
  assert.equal(service.cachedDocument("a", 111), undefined);
});
